using Microsoft.Extensions.Logging;

namespace Plugin.Services;

public class ConfigurationService
{
    private readonly IConfigRepository _repo;
    private readonly ILogger<ConfigurationService> _log;
    public ConfigurationService(IConfigRepository repo, ILogger<ConfigurationService> log) { _repo = repo; _log = log; }

    // Dos causas con nombre propio, un solo `false`.
    public async Task<bool> UpdateValueAsync(string key, string value, CancellationToken ct)
    {
        var row = await _repo.FindAsync(key, ct);
        if (row is null)
        {
            _log.LogWarning("Configuration {Key} not found", key);
            return false;
        }
        var affected = await _repo.UpdateAsync(row, value, ct);   // 0 filas = choque de concurrencia (rowversion)
        if (affected == 0)
        {
            _log.LogWarning("Concurrency conflict updating configuration {Key}", key);
            return false;
        }
        return true;
    }
}

using Microsoft.AspNetCore.Mvc;
using Plugin.Services;

namespace Plugin.Controllers;

[ApiController]
[Route("api/configuration")]
public class ConfigurationController : ControllerBase
{
    private readonly ConfigurationService _svc;
    public ConfigurationController(ConfigurationService svc) { _svc = svc; }

    [HttpPut("{key}")]
    public async Task<IActionResult> Update(string key, [FromBody] string value, CancellationToken ct)
    {
        var ok = await _svc.UpdateValueAsync(key, value, ct);
        if (!ok) return NotFound($"{key} not found in category");   // el conflicto de concurrencia también sale como 404
        return NoContent();
    }
}

