using Microsoft.Extensions.Logging;

namespace Plugin.Services;

public class PasswordService
{
    private readonly IUserRepository _users;
    private readonly ILogger<PasswordService> _log;
    public PasswordService(IUserRepository users, ILogger<PasswordService> log) { _users = users; _log = log; }

    // Predicado: `false` ES la respuesta completa. Distinguir «no existe» de «hash distinto» no le sirve al llamador
    // (y decírselo al usuario sería un oráculo de enumeración de cuentas).
    public async Task<bool> IsValidPassword(string user, string password, CancellationToken ct)
    {
        var u = await _users.FindAsync(user, ct);
        if (u is null)
        {
            _log.LogDebug("Login attempt for unknown user {User}", user);
            return false;
        }
        if (!Hasher.Verify(password, u.PasswordHash))
        {
            _log.LogDebug("Password mismatch for {User}", user);
            return false;
        }
        return true;
    }
}

