using Microsoft.AspNetCore.Mvc;
using Plugin.Services;

namespace Plugin.Controllers;

[ApiController]
[Route("api/auth")]
public class AuthController : ControllerBase
{
    private readonly PasswordService _passwords;
    private readonly ITokenIssuer _tokens;
    public AuthController(PasswordService passwords, ITokenIssuer tokens) { _passwords = passwords; _tokens = tokens; }

    [HttpPost("login")]
    public async Task<IActionResult> Login([FromBody] LoginRequest req, CancellationToken ct)
    {
        if (!await _passwords.IsValidPassword(req.User, req.Password, ct)) return Unauthorized();
        return Ok(new { token = _tokens.Issue(req.User) });
    }
}
